    "id": "d5-b11-5.5-003",
    "domain": "D5",
    "domainTitle": "Context Management & Reliability",
    "taskStatement": "5.5 message-batches-api / angle-03",
    "difficulty": "application",
    "scenarioId": "g-d5-b11-5.5-003",
